(() => {
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(x,d=0)=>x==null?'—':new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(x);
const pct=x=>x==null?'—':'%'+nf(x*100,1);
const groupName=g=>({UC_BUYUK_IL:'İstanbul / Ankara / İzmir',DIGER_ILLER:'Diğer iller'})[g]||g;
const statusName=s=>({strongly_efficient:'Etkin sınırda',radially_efficient_with_slack:'Radyal etkin · ek boşluk var',inefficient:'İyileştirme mesafesi var',insufficient_peer_count:'Emsal sayısı yetersiz'})[s]||s;
function filtered(data,state){return data.scores.filter(r=>(!state.deaGroup||state.deaGroup==='ALL'||r.group===state.deaGroup)&&(!state.deaCluster||state.deaCluster==='ALL'||r.cluster_id===state.deaCluster)&&(!state.deaSearch||r.branch.toLocaleLowerCase('tr').includes(state.deaSearch.toLocaleLowerCase('tr')))).sort((a,b)=>a.cluster_id.localeCompare(b.cluster_id)||(a.efficiency??2)-(b.efficiency??2)||a.branch.localeCompare(b.branch));}
window.renderDEAPage=(data,state)=>{
 if(!data)return '<section class="card"><div class="card-body">Verimlilik analizi henüz çalıştırılmadı.</div></section>';
 const {config:c,summary:s,manifest:m}=data,rows=filtered(data,state),group=state.deaGroup||'ALL',cluster=state.deaCluster||'ALL',indicator=c.outputs.some(x=>x.name===state.deaIndicator)?state.deaIndicator:c.outputs[0].name;
 const field=c.outputs.find(x=>x.name===indicator),visibleClusters=data.clusters.filter(x=>group==='ALL'||x.group===group),branch=rows.find(r=>r.branch===state.deaBranch)||rows[0];
 const projection=(id,name)=>data.potentials.find(p=>p.branch===id&&p.indicator===name);
 const valid=rows.filter(r=>r.efficiency!=null),mean=valid.length?valid.reduce((a,r)=>a+r.efficiency,0)/valid.length:null;
 const bins=Array.from({length:5},(_,i)=>({label:nf(i*.2,1)+'–'+nf((i+1)*.2,1),count:valid.filter(r=>r.efficiency>=i*.2-1e-10&&(i===4?r.efficiency<=1+1e-7:r.efficiency<(i+1)*.2-1e-10)).length}));
 return `<div class="clustering-page dea-page"><div class="clustering-intro"><div><span class="badge success">Çıktı odaklı CRS-DEA</span><h2>Seçilmiş girdilere göre göreli üretim verimliliği</h2><p>${esc(m.as_of)} · ${s.branches} şube · ${s.clusters} küme. Her şube kendi kümesindeki aynı ayın gözlemleriyle karşılaştırıldı.</p></div><a class="button secondary" href="downloads/dea_package.zip" download>DEA paketini indir</a></div>${!data.active?'<p class="inline-note"><strong>Tarihsel DEA sonucu.</strong> Bu koşu güncel küme seçimi, son dönem veya kaynak veriyle eşleşmiyor. Güncel politika altında onaylı ana model yoksa bu skorlarla yeni işlem başlatılmaz.</p>':''}<div class="kpi-grid">${[['Hesaplanan / toplam',s.calculated_branches+' / '+s.branches,'Yetersiz emsal: '+s.withheld_branches],['Seçili şubelerde ortalama skor',nf(mean,3),'Betimleyici ortalama; farklı küme sınırları'],['Etkin sınırdaki şube',valid.filter(r=>r.status==='strongly_efficient').length,'Seçili görünümde; skor 1 ve boşluk yok'],['İnceleme işareti',valid.filter(r=>r.high_growth_flag).length,'%100 üzerinde ortak radyal artış mesafesi']].map(([label,value,detail])=>`<div class="kpi"><div class="kpi-head">${label}</div><div class="kpi-value">${esc(value)}</div><small>${esc(detail)}</small></div>`).join('')}</div>${window.renderDEAInputChecks?.(data.input_audit)||''}<section class="card space-bottom"><div class="card-head"><div><h2>Girdi, çıktılar ve skorun anlamı</h2><p>Bu analiz şubenin aynı girdi düzeyiyle emsal sınıra olan mesafesini ölçer. Maliyet veya risk ayarlı kârlılık ölçüsü değildir.</p></div><a class="button secondary small" href="downloads/dea_methodology.md" download>Metodoloji ve kaynaklar</a></div><div class="card-body text-detail"><p><strong>Girdi:</strong> ${c.inputs.map(x=>esc(x.label)+(x.transform==='divide_by_calendar_days'?' = müşteri-gün / ayın takvim günleri':'')).join('; ')}.</p><p><strong>Çıktılar:</strong> ${c.outputs.map(x=>esc(x.label)).join('; ')}.</p><p>Verimlilik = 1 / φ. Ortak radyal artış = φ − 1. Örneğin skor 0,80 ise üç çıktıda birlikte radyal mesafe %25'tir. İkinci aşamada ürün bazında ek boşluklar bulunabilir.</p><p>CRS orantılı ölçeklenme varsayar. Aynı emsallerle VRS skoru da duyarlılık için hesaplandı. Kümeler farklı sınırlar kullandığından şubeler banka genelinde tek bir verimlilik sırasına konulamaz.</p><p><strong>Projeksiyonlar gelecek ay büyüme tahmini veya şube hedefi değildir.</strong> Mevcut aylık ortalama bakiyeler kullanıldı; Ocak 2027 bütçesi dağıtılmadı.</p></div></section><div class="cluster-controls"><label>Coğrafi grup<select id="dea-group"><option value="ALL">Tüm gruplar</option>${[...new Set(data.scores.map(r=>r.group))].map(g=>`<option value="${esc(g)}" ${g===group?'selected':''}>${esc(groupName(g))}</option>`).join('')}</select></label><label>Emsal kümesi<select id="dea-cluster"><option value="ALL">Tüm kümeler</option>${visibleClusters.map(x=>`<option value="${esc(x.cluster_id)}" ${x.cluster_id===cluster?'selected':''}>${esc(x.cluster_id)} · ${x.n} şube</option>`).join('')}</select></label><label>Ürün projeksiyonu<select id="dea-indicator">${c.outputs.map(x=>`<option value="${esc(x.name)}" ${x.name===indicator?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><label>Şube ara<input type="search" id="dea-search" value="${esc(state.deaSearch||'')}" placeholder="Şube kodu"></label></div><div class="group-panels"><section class="card space-bottom"><div class="card-head"><div><h2>Küme boyutu ve etkin sınır</h2><p>Ön kontrol: n ≥ max(m×s, 3(m+s)). ${c.inputs.length} girdi / ${c.outputs.length} çıktı için en az ${s.required_cluster_n} şube. Bu kural yeterlilik garantisi vermez. Seçilen kümeler, tanımlı bütün girdi senaryolarının ortak boyut sınırını da karşılar.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Küme</th><th class="num">Şube</th><th class="num">Medyan skor</th><th class="num">Etkin şube</th><th>Kontrol</th></tr></thead><tbody>${visibleClusters.filter(x=>cluster==='ALL'||x.cluster_id===cluster).map(x=>`<tr><td>${esc(x.cluster_id)}</td><td class="num">${x.n}</td><td class="num">${nf(x.median_efficiency,3)}</td><td class="num">${nf(x.strongly_efficient)}</td><td>${!x.size_rule_passed?'Skor üretilmedi':x.discrimination_review?'Ayırt etme gücünü incele':'Boyut ön kontrolü geçti'}</td></tr>`).join('')}</tbody></table></div></section><section class="card space-bottom"><div class="card-head"><div><h2>Seçili şubelerin skor dağılımı</h2><p>1 etkin sınırı gösterir. Dağılım farklı küme sınırlarından gelen skorları betimler.</p></div></div><div class="card-body">${bins.map(b=>`<div class="cluster-size-row"><span>${b.label}</span><div class="bar-track"><div class="bar-fill" style="width:${b.count/Math.max(...bins.map(x=>x.count),1)*100}%;background:#318975"></div></div><strong>${b.count} şube</strong></div>`).join('')}</div></section></div><section class="card space-bottom"><div class="card-head"><div><h2>Şube skorları ve ${esc(field.label)}</h2><p>${rows.length} şube. Sıralama inceleme kolaylığı içindir; farklı kümeler arasında banka genelinde başarı sırası değildir.</p></div><a class="button secondary small" href="downloads/dea_scores.csv" download>Bütün skorları indir</a></div><div class="table-wrap cluster-assignments"><table class="data-table"><thead><tr><th>Şube / küme</th><th class="num">CRS skor</th><th class="num">VRS skor</th><th class="num">Ölçek verimliliği</th><th class="num">Ortak radyal mesafe</th><th class="num">Gerçekleşen</th><th class="num">Sınır projeksiyonu</th><th class="num">Ürün artış mesafesi</th><th>Durum</th></tr></thead><tbody>${rows.length?rows.map(r=>{const p=projection(r.branch,indicator);return `<tr><td>${esc(r.branch)}<span class="sub">${esc(r.cluster_id)}</span></td><td class="num">${nf(r.efficiency,3)}</td><td class="num">${nf(r.vrs_efficiency,3)}</td><td class="num">${nf(r.scale_efficiency,3)}</td><td class="num">${pct(r.radial_growth)}</td><td class="num">${nf(p?.actual)}</td><td class="num">${nf(p?.frontier_projection)}</td><td class="num">${pct(p?.improvement_ratio)}${p?.zero_actual?'<span class="sub">Sıfır gerçekleşme; yüzde tanımsız</span>':''}</td><td>${esc(statusName(r.status))}${r.high_growth_flag?'<span class="sub">Yüksek mesafe; iş incelemesi</span>':''}</td></tr>`;}).join(''):'<tr><td colspan="9">Aramayla eşleşen şube yok.</td></tr>'}</tbody></table></div></section>${branch?`<section class="card space-bottom"><div class="card-head"><div><h2>Şube ayrıntısı ve emsal birleşimi</h2><p>λ katsayıları portföy transferi veya pay değildir; CRS'de toplamları 1 olmak zorunda değildir. Alternatif optimum emsaller bulunabilir.</p></div></div><div class="cluster-controls"><label>İncelenecek şube<select id="dea-branch">${rows.map(r=>`<option value="${esc(r.branch)}" ${r.branch===branch.branch?'selected':''}>${esc(r.branch)} · ${esc(r.cluster_id)}</option>`).join('')}</select></label></div><div class="card-body text-detail"><p>${c.inputs.map(x=>esc(x.label)+': '+nf(data.input_rows.find(r=>r.__branch===branch.branch)?.[x.name],3)+' '+esc(x.unit)).join(' · ')}.</p><p>${esc(branch.branch)} · ${esc(statusName(branch.status))}. ${data.peers.filter(p=>p.branch===branch.branch).map(p=>esc(p.peer_branch)+' × '+nf(p.lambda,4)+(p.is_self?' (kendisi)':'')).join(' + ')||'Bu şube için emsal projeksiyonu üretilmedi.'}</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Gösterge</th><th class="num">Gerçekleşen</th><th class="num">Ortak radyal projeksiyon</th><th class="num">Ek çıktı boşluğu</th><th class="num">Sınır projeksiyonu</th></tr></thead><tbody>${c.outputs.map(x=>{const p=projection(branch.branch,x.name);return `<tr><td>${esc(x.label)}</td><td class="num">${nf(p?.actual)}</td><td class="num">${nf(p?.radial_projection)}</td><td class="num">${nf(p?.output_slack)}</td><td class="num">${nf(p?.frontier_projection)}</td></tr>`;}).join('')}</tbody></table></div></section>`:''}<section class="card"><div class="card-body text-detail"><p>Veriler sentetiktir. DEA sınırı aykırı değerlere ve seçilen girdi/çıktı tanımına duyarlıdır. Skor 1 bütün ürünlerde liderlik veya gelecek ay erişilebilir büyüme garantisi vermez. Küçük emsal grubu oluşursa bütün işlem durur; şubeler elenip kısmi sonuç üretilmez. Müşteriler veya geçmiş aylar ek şubeymiş gibi sayılmaz.</p><div class="selection-links"><a class="button secondary small" href="downloads/dea_potentials.csv" download>Ürün projeksiyonları</a><a class="button secondary small" href="downloads/dea_peers.csv" download>Emsal katsayıları</a><a class="button secondary small" href="downloads/dea_input.csv" download>Girdi ve çıktı kesiti</a><a class="button secondary small" href="downloads/dea_config.json" download>Alan sözlüğü</a></div></div></section></div>`;
};
})();
